import{d as e,i as t}from"./index-BVdLvPw-.js";import{t as n}from"./BlogPost-BCN0DswP.js";var r=t();function i(){return(0,r.jsxs)(n,{path:`/blog-core-web-vitals`,children:[(0,r.jsx)(`p`,{children:`Core Web Vitals are three measurements Google uses to judge real-world user experience. Good scores help visitors stay, and they form part of how Google evaluates pages.`}),(0,r.jsx)(`p`,{children:`They are not a magic ranking switch. Google has been clear that relevant, helpful content comes first, and page experience is one signal among many. But a slow or jumpy site loses enquiries regardless of where it ranks, because people give up and go back to the search results. That makes Core Web Vitals worth understanding even if SEO isn't your main concern.`}),(0,r.jsx)(`h2`,{children:`The three measures`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Largest Contentful Paint (LCP):`}),` how quickly the main content appears. Aim for 2.5 seconds or less.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Interaction to Next Paint (INP):`}),` how quickly the page responds when someone taps or clicks. Aim for 200 milliseconds or less.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Cumulative Layout Shift (CLS):`}),` how much the layout jumps while loading. Aim for 0.1 or less.`]})]}),(0,r.jsx)(`p`,{children:`Google rates each metric as good, needs improvement or poor. As a rough guide, LCP over 4 seconds, INP over 500 milliseconds or CLS over 0.25 is rated poor. A page passes when at least 75% of real visits meet the good threshold, measured separately for mobile and desktop.`}),(0,r.jsx)(`h3`,{children:`What each one means in practice`}),(0,r.jsxs)(`p`,{children:[(0,r.jsx)(`b`,{children:`LCP`}),` is usually your hero image, a large heading or a banner. If a visitor on a phone waits four seconds staring at a blank space where your main photo should be, that is a poor LCP.`]}),(0,r.jsxs)(`p`,{children:[(0,r.jsx)(`b`,{children:`INP`}),` replaced the older First Input Delay (FID) metric in 2024. FID only measured the first tap. INP looks at the responsiveness of interactions across the whole visit, such as opening a menu, ticking a box on a form or pressing "Add to cart". A page can load quickly and still feel sluggish if heavy scripts keep the browser busy.`]}),(0,r.jsxs)(`p`,{children:[(0,r.jsx)(`b`,{children:`CLS`}),` is the annoying jump when you go to tap a button and a banner loads above it, pushing everything down. It often comes from images without set dimensions, late-loading ads, cookie notices and web fonts swapping in.`]}),(0,r.jsx)(`h2`,{children:`Common fixes`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Compress and correctly size images.`}),(0,r.jsx)(`li`,{children:`Remove unused scripts and plugins.`}),(0,r.jsx)(`li`,{children:`Reserve space for images and embeds so the layout doesn't jump.`}),(0,r.jsx)(`li`,{children:`Use good hosting and caching.`})]}),(0,r.jsx)(`h3`,{children:`Improving LCP`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Serve images in modern formats such as WebP or AVIF, at the size they are actually displayed. A 4000-pixel photo shrunk to fit a phone screen is a common culprit.`}),(0,r.jsx)(`li`,{children:`Don't lazy-load the main hero image. Lazy loading is great for images further down the page, but the first image should load straight away.`}),(0,r.jsx)(`li`,{children:`Check server response time. Cheap shared hosting, no caching and slow database queries all delay everything else. A content delivery network (CDN) helps if you have visitors in several countries.`}),(0,r.jsx)(`li`,{children:`Avoid sliders and carousels at the top of the page. They usually load several large images and scripts before anything useful appears.`})]}),(0,r.jsx)(`h3`,{children:`Improving INP`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Audit third-party scripts: chat widgets, tracking tags, review badges, heat maps and social feeds. Each one competes for the browser's attention. Keep the ones you actually use.`}),(0,r.jsx)(`li`,{children:`Break up long JavaScript tasks so the browser can respond to taps in between.`}),(0,r.jsx)(`li`,{children:`On WordPress and similar platforms, be wary of page builders and plugin stacks that load code on every page, even where it isn't needed.`})]}),(0,r.jsx)(`h3`,{children:`Improving CLS`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Set width and height (or an aspect ratio) on every image and video.`}),(0,r.jsx)(`li`,{children:`Give ad slots, embeds and cookie banners a fixed space, or show banners as an overlay rather than pushing content down.`}),(0,r.jsx)(`li`,{children:`Load web fonts sensibly and choose a fallback font of similar size, so text doesn't reflow when the font arrives.`})]}),(0,r.jsx)(`h2`,{children:`How to check yours`}),(0,r.jsx)(`p`,{children:`Use Google PageSpeed Insights or the Core Web Vitals report in Google Search Console.`}),(0,r.jsxs)(`ol`,{children:[(0,r.jsx)(`li`,{children:`Open PageSpeed Insights and enter your home page and one or two key pages, such as a main service page.`}),(0,r.jsx)(`li`,{children:`Look first at the top section, which shows real-user (field) data collected from Chrome users over the previous 28 days. This is what Google uses.`}),(0,r.jsx)(`li`,{children:`The lower section is a lab test from Lighthouse. It is useful for diagnosing problems, but it is a single simulated visit, so the score can vary between runs. Lighthouse can't measure INP directly, so it shows Total Blocking Time as a rough stand-in.`}),(0,r.jsx)(`li`,{children:`In Search Console, open the Core Web Vitals report to see which groups of pages are good, need improvement or are poor, and which metric is the problem.`})]}),(0,r.jsx)(`p`,{children:`Smaller sites often don't have enough traffic for field data. In that case, rely on the lab results and test on a real mid-range phone over mobile data, not just your office computer on fast broadband.`}),(0,r.jsx)(`h2`,{children:`Common mistakes`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Chasing a perfect 100 lab score instead of fixing what real visitors experience.`}),(0,r.jsx)(`li`,{children:`Installing yet another "speed plugin" on top of a bloated site, rather than removing what slows it down.`}),(0,r.jsx)(`li`,{children:`Testing only the home page. Service pages, blog posts and landing pages used for ads matter just as much.`}),(0,r.jsx)(`li`,{children:`Adding new tracking scripts for a marketing campaign without checking the effect on speed.`}),(0,r.jsx)(`li`,{children:`Expecting instant results. Field data covers a rolling 28 days, so improvements take a few weeks to show fully.`})]}),(0,r.jsx)(`h2`,{children:`Quick checklist`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Hero image compressed, correctly sized and not lazy-loaded.`}),(0,r.jsx)(`li`,{children:`Unused plugins and third-party scripts removed.`}),(0,r.jsx)(`li`,{children:`All images and embeds have reserved space.`}),(0,r.jsx)(`li`,{children:`Caching enabled and hosting responds quickly.`}),(0,r.jsx)(`li`,{children:`Key pages tested on mobile in PageSpeed Insights.`}),(0,r.jsx)(`li`,{children:`Search Console Core Web Vitals report reviewed monthly.`})]}),(0,r.jsxs)(`p`,{children:[`Speed works best alongside clear content and solid `,(0,r.jsx)(e,{to:`/seo`,children:`search engine optimisation`}),`. If you rely on local customers, our `,(0,r.jsx)(e,{to:`/blog-local-seo-checklist`,children:`local SEO checklist`}),` covers the other half of getting found.`]}),(0,r.jsx)(`h2`,{children:`Frequently asked questions`}),(0,r.jsx)(`h3`,{children:`Will fixing Core Web Vitals push my site to the top of Google?`}),(0,r.jsx)(`p`,{children:`Not on its own. Relevance and content quality matter more. Good Core Web Vitals help in close contests and, more importantly, stop you losing visitors who arrive and leave because the page is slow.`}),(0,r.jsx)(`h3`,{children:`Why does my PageSpeed score change every time I test?`}),(0,r.jsx)(`p`,{children:`The lab score is a single simulated visit, so network and server conditions cause variation. Focus on the field data section and on trends over time rather than one result.`}),(0,r.jsx)(`h3`,{children:`Is it better to fix my current site or rebuild it?`}),(0,r.jsxs)(`p`,{children:[`Many sites improve a lot with image optimisation, plugin clean-up and better hosting. If the site relies on a heavy theme or page builder that loads lots of code everywhere, a rebuild with a lean `,(0,r.jsx)(e,{to:`/design`,children:`website design`}),` can be more cost-effective long term.`]}),(0,r.jsx)(`h3`,{children:`Does hosting really make a difference?`}),(0,r.jsxs)(`p`,{children:[`Yes. A slow server delays every metric, especially LCP. Reliable hosting, caching and regular `,(0,r.jsx)(e,{to:`/cloud-maintenance`,children:`cloud maintenance`}),` keep response times steady as your site grows.`]}),(0,r.jsxs)(`p`,{children:[`Our `,(0,r.jsx)(e,{to:`/website-development`,children:`websites`}),` are built for speed from day one.`]})]})}export{i as default};